raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R08-01",
   "status": "OK",
   "label": "이자 지급시기",
   "source": {
    "quote": "매년 2월, 5월, 8월, 11월의 둘째 금요일에 결산하여 다음날 원금에 더함"
   },
   "condition": {
    "not": {
     "in": [
      {
       "var": "contract.termination_type"
      },
      [
       "MATURITY",
       "EARLY",
       "PARTIAL",
       "MID_TERM"
      ]
     ]
    }
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 1,
    "unit": "MONTH"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R08-02",
   "status": "OK",
   "label": "5년 경과 후 이자 계산 방식 변경",
   "source": {
    "quote": "예금의 이자는 최종거래일로부터 5년이 경과한 날부터는 이자에 원금을 더하지 않고, 계좌해지 또는 추가 입출금 거래 발생일에 일괄 계산하여 지급할 수 있습니다"
   },
   "condition": {
    "and": [
     {
      "gte": [
       {
        "var": "account.last_transaction_date"
       },
       {
        "date": {
         "year": "contract.opening_date.year",
         "month": "contract.opening_date.month",
         "day": "contract.opening_date.day"
        },
        "offset_years": 5
       }
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.termination_type"
        },
        [
         "MATURITY",
         "EARLY",
         "PARTIAL",
         "MID_TERM"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_SUBTRACT",
    "value": 1,
    "unit": "MONTH"
   }
  }
 ]
}

