   "label": "기본금리 적용 기간",
   "source": {
    "quote": "예금이자는 예금일부터 지급일 전일까지(결산시에는 지난 원가일부터 원가일 전일까지)를 이자계산 기간으로 하고, 매일의 최종잔액을 평균하여 결산일 현재 지점에 고시한 기본금리로 계산함"
   },
   "condition": {
    "and": [
     {
      "not": {
       "in": [
        {
         "var": "event.type"
        },
        [
         "TERMINATION",
         "NAME_CHANGE"
        ]
       ]
      }
     },
     {
      "exists": {
       "event": "DEPOSIT",
       "within": {
        "ref": "$accounting_period"
       }
      }
     }
    ]
   },
   "let": {
    "accounting_period": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "contract.base_rate",
    "unit": "%"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R09-02",
   "status": "OK",
   "label": "특별금리 적용 기간",
