         "NAME_CHANGE"
        ]
       ]
      }
     },
     {
      "exists": {
       "event": "RESERVE_OFF",
       "within": {
        "ref": "$reserve_period"
       }
      }
     }
    ]
   },
   "let": {
    "reserve_period": {
     "month_range": {
      "from": {
       "anchor": "event.reserve_start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "event.reserve_end_date",
       "offset_months": 0,
       "day": "last"
      }
     }
    }
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "contract.special_rate",
    "unit": "%"
   }
  }
 ]
}

