        },
        [
         "0"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.5,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R11-02",
   "status": "OK",
   "label": "저금통 해제",
   "source": {
    "quote": "다른 예금 상품으로 전환하는 경우 저금통은 자동 해제됨"
   },
   "condition": {
    "exists": {
     "event": "PRODUCT_SWITCH",
     "where": {
      "direction": [
       "OUT"
      ]
     }
    }
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "RESERVE_OFF"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R11-03",
   "status": "OK",
   "label": "저금통 설정 금액 출금 가능",
   "source": {
    "quote": "저금통으로 설정된 금액은 계좌 출금(이체)이 불가하며, 필요 금액만큼 저금통 금액 차감 처리 후 계좌출금(이체) 가능"
   },
   "condition": {
    "exists": {
     "event": "RESERVE_ON"
    }
   },
   "effect": {
    "type": "RESTRICT",
    "target": "WITHDRAWAL"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R11-04",
   "status": "OK",
   "label": "저금통 설정금액 출금 시 차감 처리",
   "source": {
    "quote": "저금통으로 설정된 금액은 계좌 출금(이체)이 불가하며, 필요 금액만큼 저금통 금액 차감 처리 후 계좌출금(이체) 가능"
   },
   "condition": {
    "exists": {
     "event": "WITHDRAWAL"
    }
   },
   "effect": {
    "type": "LIMIT_AMOUNT",
    "value": "account.reserved_amount"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R11-05",
   "status": "OK",
   "label": "저금통 설정 재가능 조건",
   "source": {
    "quote": "다른 예금 상품에서 이 상품으로 전환하는 경우 도래하는 결산일 이후 저금통 설정 가능"
   },
   "condition": {
    "exists": {
     "event": "PRODUCT_SWITCH",
     "where": {
      "direction": [
       "IN"
      ]
     }
    }
   },
   "effect": {
    "type": "PRODUCT_SWITCH_TO",
    "target": "RESERVE_ON"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R11-06",
   "status": "UNSUPPORTED",
   "label": "거래 정정 시 특별금리 적용",
   "source": {
    "quote": "거래 정정 등 부득이한 사유로 저금통 설정금액보다 실제 잔액이 더 적은 경우에는 실제 잔액에 대하여 결산일 현재 지점에 게시한 특별금리 적용"
   },
   "condition": {
    "exists": {
     "event": "TRANSACTION_CORRECTION"
    }
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "account.balance"
   }
  }
 ]
}

