   },
   "condition": {
    "exists": {
     "event": "PRODUCT_SWITCH",
     "where": {
      "direction": [
       "OUT"
      ]
     }
    }
   },
   "effect": {
    "type": "RESTRICT",
    "target": "PRODUCT_SWITCH_IN"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R23-05",
   "status": "OK",
   "label": "저금통 설정 금액 제한",
